import logging
import socket

from taf.hw.pdu.device_status import DeviceStatus
from taf.hw.pdu.devices.base import PDU


class SocketAdapter:
    def __init__(self, ip, port):
        """ip: str, port: str | int"""
        self.connection_address = (ip, port)
        self.instrument = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        self.instrument.connect(self.connection_address)

    def write(self, command):
        """command: str"""
        self.instrument.sendall(f"{command}\n".encode())

    def __del__(self):
        self.instrument.close()

    def close_connection(self):
        self.instrument.close()


class PS9000(PDU):

    AVAILABLE_PORT = 1

    def __init__(self, ip, port):
        """ip: str, port: str | int"""
        super(PS9000, self).__init__(ip)
        logging.warning(f"{self.__class__.__name__} is deprecated. "
                "Please use ElektroAutomatik 'PS9080-100' model instead.")
        self.connector = SocketAdapter(ip, port)
        self.connector.write("SYST:REM;LANG CIIL")

    def set_voltage(self, port, voltage):
        """
        port: ignored, i.e., the operation is always performed on the only AVAILABLE_PORT = 1
        voltage: float
        """
        self.connector.write(f"VOLT {voltage:.2f}")

    def power_on(self, port):
        """
        port: required to fit the signature but the value is ignored, i.e.,
        the operation is always performed on the AVAILABLE_PORT = 1
        """
        return super(PS9000, self).power_on(port=PS9000.AVAILABLE_PORT)

    def power_off(self, port):
        """
        port: required to fit the signature but the value is ignored, i.e.,
        the operation is always performed on the AVAILABLE_PORT = 1
        """
        return super(PS9000, self).power_off(port=PS9000.AVAILABLE_PORT)

    def reset(self, ports=None, time_interval=2):
        if ports is None:
            ports = [PS9000.AVAILABLE_PORT]
        return super(PS9000, self).reset(ports, time_interval)

    def _port_setting(self):
        return {
            DeviceStatus.OFF: "0",
            DeviceStatus.ON: "1",
        }

    def _set_port_status(self, port, status):
        """This device have just one port. Port argument is omitted."""
        self.connector.write(f"OUTP {self._port_setting()[status]}")

    def get_port_status(self, port):
        raise NotImplementedError("This method is not implemented.")

    def teardown(self):
        self.connector.close_connection()
